import java.util.*;
import javax.servlet.*;
import javax.servlet.http.*;
import org.apache.commons.text.StringEscapeUtils;

public class ReportServlet extends HttpServlet {
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    // Allowlist for report types - looks like a defense but doesn't cover the vuln
    private static final Set<String> VALID_TYPES = Set.of("summary", "detail", "audit", "compliance");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp) 
            throws ServletException, IOException {
        String action = req.getParameter("action");

        if ("export".equals(action)) {
            handleExport(req, resp);
        } else if ("search".equals(action)) {
            handleSearch(req, resp);
        } else {
            handleDefault(req, resp);
        }
    }

    // This endpoint has proper parameterized queries - red herring
    private void handleDefault(HttpServletRequest req, HttpServletResponse resp) 
            throws IOException {
        String type = req.getParameter("type");
        if (type == null || !VALID_TYPES.contains(type)) {
            resp.sendError(400, "Invalid report type");
            return;
        }
        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             PreparedStatement ps = conn.prepareStatement(
                 "SELECT id, title, created_at FROM reports WHERE type = ? ORDER BY created_at DESC")) {
            ps.setString(1, type);
            ResultSet rs = ps.executeQuery();
            resp.setContentType("application/json");
            // ... serialize results
        } catch (SQLException e) {
            resp.sendError(500);
        }
    }

    // VULNERABLE: SQL injection via ORDER BY clause
    private void handleSearch(HttpServletRequest req, HttpServletResponse resp) 
            throws IOException {
        String keyword = req.getParameter("q");
        String sortCol = req.getParameter("sort");
        String sortDir = req.getParameter("dir");

        if (keyword == null || keyword.length() > 200) {
            resp.sendError(400);
            return;
        }

        // keyword is properly parameterized - looks safe
        // but sortCol is concatenated into ORDER BY (can't parameterize identifiers)
        String baseQuery = "SELECT id, title, author, created_at, status FROM reports WHERE title LIKE ?";

        // This "validation" is intentionally weak - allows bypass
        if (sortCol != null && sortCol.matches("[a-zA-Z_,() ]+")) {
            baseQuery += " ORDER BY " + sortCol;
            if ("desc".equalsIgnoreCase(sortDir)) {
                baseQuery += " DESC";
            }
        }

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             PreparedStatement ps = conn.prepareStatement(baseQuery)) {
            ps.setString(1, "%" + keyword + "%");
            ResultSet rs = ps.executeQuery();
            resp.setContentType("application/json");
            PrintWriter out = resp.getWriter();
            out.print("[");
            boolean first = true;
            while (rs.next()) {
                if (!first) out.print(",");
                out.printf("{\"id\":%d,\"title\":\"%s\",\"author\":\"%s\",\"status\":\"%s\"}",
                    rs.getInt("id"),
                    StringEscapeUtils.escapeJson(rs.getString("title")),
                    StringEscapeUtils.escapeJson(rs.getString("author")),
                    StringEscapeUtils.escapeJson(rs.getString("status")));
                first = false;
            }
            out.print("]");
        } catch (SQLException e) {
            // Error message intentionally vague
            resp.sendError(500, "Query failed");
        }
    }

    // Another red herring - SSRF-looking but actually safe
